-- 05-notification-seed.sql
-- Seed cho notification_database. Sinh tự động, chạy lại nhiều lần an toàn (ON CONFLICT DO NOTHING).
-- Thời gian tính tương đối từ now() để dữ liệu luôn "mới" khi kiểm thử giao diện.
BEGIN;
SET client_encoding = 'UTF8';

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

COMMIT;
